INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich Arbeitspakete ohne Ziele definieren?', 2, '[{"text": "Nein", "correct": true, "because": "Ziele geben Richtung"}, {"text": "Ja", "correct": false, "because": "Fehlende Orientierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Definition von Arbeitspaketen?', 3, '[{"text": "Projektstrukturierung", "correct": true, "because": "Teilt Aufgaben auf"}, {"text": "Design", "correct": false, "because": "Anderer Fokus"}, {"text": "Performance", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Arbeitspaket?', 5, '[{"text": "Aufgabenbeschreibung", "correct": true, "because": "Definiert Inhalt"}, {"text": "Zeitrahmen", "correct": true, "because": "Setzt Dauer"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}, {"text": "Teamfotos", "correct": false, "because": "Nicht nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitspakete brauchen Verantwortliche. b) Sie sind immer groß.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) überschaubar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Definition von Arbeitspaketen?', 4, '[{"text": "Abhängigkeiten", "correct": false, "because": "Zeigt Zusammenhänge"}, {"text": "Ressourcen", "correct": false, "because": "Definiert Bedarf"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Arbeitspakete immer detailliert sein müssen?', 2, '[{"text": "Nein", "correct": true, "because": "Übersicht kann reichen"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich zur Definition von Arbeitspaketen?', 3, '[{"text": "MS Project", "correct": true, "because": "Strukturiert Aufgaben"}, {"text": "Notepad", "correct": false, "because": "Unstrukturiert"}, {"text": "E-Mail", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Arbeitspakete effektiv?', 5, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Machbarkeit", "correct": true, "because": "Realistisch umsetzbar"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}, {"text": "Lange Beschreibungen", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Arbeitspakete sind nur für große Projekte. b) Sie brauchen keine Zeitangabe. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Auch kleine Projekte, Zeit nötig"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Arbeitspakete?', 4, '[{"text": "Zielsetzung", "correct": false, "because": "Gibt Richtung"}, {"text": "Verantwortlicher", "correct": false, "because": "Sichert Umsetzung"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Arbeitspakete nur für Teams?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Einzelprojekte"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Details sind bei Arbeitspaketen entscheidend?', 4, '[{"text": "Aufgaben", "correct": true, "because": "Definiert Arbeit"}, {"text": "Meilensteine", "correct": true, "because": "Markiert Fortschritt"}, {"text": "Farbschema", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Arbeitspakete ohne Abhängigkeiten definiert werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängigkeiten koordinieren"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Definition von Arbeitspaketen?', 3, '[{"text": "Übersichtlichkeit", "correct": true, "because": "Fördert Planung"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}, {"text": "Komplexität", "correct": false, "because": "Verwirrt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitspakete brauchen Ressourcen. b) Sie sind immer unabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft abhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Arbeitspaket-Definition?', 5, '[{"text": "Klarer Plan", "correct": true, "because": "Strukturiert Projekt"}, {"text": "Effizienz", "correct": true, "because": "Teilt Arbeit sinnvoll"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Arbeitspaketen unwichtig?', 3, '[{"text": "Zeitrahmen", "correct": false, "because": "Setzt Grenzen"}, {"text": "Aufgaben", "correct": false, "because": "Definiert Inhalt"}, {"text": "Monitorgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Arbeitspakete die Zeitpläne?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen sie"}, {"text": "Ja", "correct": false, "because": "Zeitpläne zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Arbeitspakete nur für Software sind?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Projekte"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Arbeitspakete entscheidend?', 4, '[{"text": "Klarheit", "correct": true, "because": "Verhindert Missverständnisse"}, {"text": "Hohe Komplexität", "correct": false, "because": "Verwirrt"}, {"text": "Statische Daten", "correct": false, "because": "Nicht primär"}]');
